/* Stable listings: only collectors mutate entries before DONE publication.
 * The coordinator owns attachment metadata and the global scheduling tokens. */
typedef struct ListingJob ListingJob;
typedef struct WalkEntry {
    CuStr name;
    CuDirKind kind;
    ListingJob *prefetch;
    int eligible;
} WalkEntry;
struct ListingJob {
    CuArena arena;
    char *path;
    CuVec entries;
    int error;
    int operation;
    int state;
    int token;
};
typedef struct ListingWorker {
    Pool *pool;
    CuThread *thread;
} ListingWorker;
struct Pool {
    CuArena arena;
    CuMutex *mutex;
    CuCond *work;
    CuCond *completed;
    ListingWorker workers[32];
    ListingJob *slots[32];
    int count;
    int started;
    int ready;
    int stop;
    int pending;
};

static int listing_resource(int error)
{
    return error == ENOMEM || error == E2BIG || error == EMFILE || error == ENFILE;
}

#ifndef FYND_SORT_STEP
#define FYND_SORT_STEP() ((void)0)
#endif

static int entry_compare(const void *a, const void *b)
{
    const WalkEntry *x;
    const WalkEntry *y;
    x = (const WalkEntry *)a;
    y = (const WalkEntry *)b;
    FYND_SORT_STEP();
    return strcmp(x->name.ptr, y->name.ptr);
}

static void entry_insert(WalkEntry *entries, size_t count)
{
    WalkEntry saved;
    size_t i;
    size_t j;
    for (i = 1; i < count; ++i) {
        saved = entries[i];
        j = i;
        while (j != 0) {
            FYND_SORT_STEP();
            if (strcmp(entries[j - 1].name.ptr, saved.name.ptr) <= 0)
                break;
            entries[j] = entries[j - 1];
            --j;
        }
        entries[j] = saved;
    }
}

static unsigned int entry_byte(const WalkEntry *entry, size_t depth)
{
    FYND_SORT_STEP();
    return (unsigned char)entry->name.ptr[depth];
}

static void entry_swap(WalkEntry *a, WalkEntry *b)
{
    WalkEntry saved;
    saved = *a;
    *a = *b;
    *b = saved;
}

/* Each equal partition shares a nonzero prefix. The fixed partition budget
 * bounds recursion and repeated prefix work; fallback compares full names. */
static void entry_radix(WalkEntry *entries, size_t count, size_t depth,
                        unsigned int budget)
{
    size_t low;
    size_t at;
    size_t high;
    unsigned int a;
    unsigned int b;
    unsigned int c;
    unsigned int pivot;
    unsigned int key;
    if (count < 2)
        return;
    if (count <= 16) {
        entry_insert(entries, count);
        return;
    }
    if (budget == 0) {
        qsort(entries, count, sizeof(WalkEntry), entry_compare);
        return;
    }
    a = entry_byte(&entries[0], depth);
    b = entry_byte(&entries[count / 2], depth);
    c = entry_byte(&entries[count - 1], depth);
    pivot = a < b ? (b < c ? b : (a < c ? c : a)) :
                    (a < c ? a : (b < c ? c : b));
    low = 0;
    at = 0;
    high = count;
    while (at < high) {
        key = entry_byte(&entries[at], depth);
        if (key < pivot) {
            entry_swap(&entries[low], &entries[at]);
            ++low;
            ++at;
        } else if (key > pivot) {
            --high;
            entry_swap(&entries[at], &entries[high]);
        } else
            ++at;
    }
    entry_radix(entries, low, depth, budget - 1);
    if (pivot != 0)
        entry_radix(entries + low, high - low, depth + 1, budget - 1);
    entry_radix(entries + high, count - high, depth, budget - 1);
}

static void entry_sort(WalkEntry *entries, size_t count)
{
    entry_radix(entries, count, 0, 32);
}

#ifndef FYND_LISTING_COLLECT
#define FYND_LISTING_COLLECT(job) ((void)0)
#endif
#ifndef FYND_PENDING
#define FYND_PENDING(pool) ((void)0)
#endif

static void listing_collect(ListingJob *job)
{
    CuDir dir;
    CuDirEntry raw;
    WalkEntry entry;
    int next;
    FYND_LISTING_COLLECT(job);
    if (job->error != 0)
        return;
    if (!cu_dir_open(&dir, &job->arena, job->path)) {
        job->error = cu_dir_errno(&dir);
        job->operation = 1;
        cu_dir_close(&dir);
        return;
    }
    while ((next = cu_dir_next(&dir, &raw)) == 1) {
        entry.name = raw.name;
        entry.kind = raw.kind;
        entry.prefetch = NULL;
        entry.eligible = 0;
        CU_VEC_PUSH(&job->entries, &entry);
        if (cu_vec_failed(&job->entries))
            break;
    }
    job->error = cu_dir_errno(&dir);
    cu_dir_close(&dir);
    job->operation = 2;
    if (cu_arena_failed(&job->arena) || cu_vec_failed(&job->entries))
        job->error = ENOMEM;
    else if (next >= 0)
        job->error = 0;
    if (job->error == 0 && job->entries.len > 1)
        entry_sort(CU_VEC_DATA(&job->entries, WalkEntry), job->entries.len);
}

static void listing_init(ListingJob *job, const char *path)
{
    size_t n;
    cu_arena_init(&job->arena);
    CU_VEC_INIT(&job->entries, &job->arena, WalkEntry);
    job->error = 0;
    job->operation = 0;
    job->state = 0;
    job->token = 0;
    n = strlen(path);
    job->path = n == (size_t)-1 ? NULL : cu_arena_push_bytes(&job->arena, n + 1);
    if (job->path == NULL)
        job->error = ENOMEM;
    else
        memcpy(job->path, path, n + 1);
}

static void listing_worker(void *context)
{
    ListingWorker *worker;
    Pool *pool;
    ListingJob *job;
    int i;
    worker = (ListingWorker *)context;
    pool = worker->pool;
    cu_mutex_lock(pool->mutex);
    for (;;) {
        job = NULL;
        if (pool->ready && !pool->stop)
            for (i = 0; i < pool->count; ++i)
                if (pool->slots[i] != NULL && pool->slots[i]->state == 1) {
                    job = pool->slots[i];
                    job->state = 2;
                    break;
                }
        if (pool->stop)
            break;
        if (job == NULL) {
            cu_cond_wait(pool->work, pool->mutex);
            continue;
        }
        cu_mutex_unlock(pool->mutex);
        listing_collect(job);
        cu_mutex_lock(pool->mutex);
        job->state = 3;
        cu_cond_broadcast(pool->completed);
    }
    cu_mutex_unlock(pool->mutex);
}

static void pool_cancel(Pool *pool)
{
    int i;
    if (pool->mutex == NULL)
        return;
    cu_mutex_lock(pool->mutex);
    pool->stop = 1;
    for (i = 0; i < pool->count; ++i)
        if (pool->slots[i] != NULL && pool->slots[i]->state == 1)
            pool->slots[i]->state = 3;
    if (pool->work != NULL)
        cu_cond_broadcast(pool->work);
    if (pool->completed != NULL)
        cu_cond_broadcast(pool->completed);
    cu_mutex_unlock(pool->mutex);
}

static void pool_finish(Pool *pool)
{
    int i;
    pool_cancel(pool);
    for (i = 0; i < pool->started; ++i)
        cu_thread_join(pool->workers[i].thread);
    if (pool->completed != NULL)
        cu_cond_destroy(pool->completed);
    if (pool->work != NULL)
        cu_cond_destroy(pool->work);
    if (pool->mutex != NULL)
        cu_mutex_destroy(pool->mutex);
    cu_arena_release(&pool->arena);
}

static int pool_start(Pool *pool, int count)
{
    int i;
    cu_arena_init(&pool->arena);
    pool->mutex = NULL;
    pool->work = NULL;
    pool->completed = NULL;
    pool->count = count;
    pool->started = 0;
    pool->ready = 0;
    pool->stop = 0;
    pool->pending = 0;
    for (i = 0; i < 32; ++i) {
        pool->slots[i] = NULL;
        pool->workers[i].pool = pool;
        pool->workers[i].thread = NULL;
    }
    if (!cu_mutex_init(&pool->mutex, &pool->arena) ||
        !cu_cond_init(&pool->work, &pool->arena) ||
        !cu_cond_init(&pool->completed, &pool->arena))
        return 0;
    for (i = 0; i < count; ++i) {
        if (!cu_thread_start(&pool->workers[i].thread, &pool->arena, 0,
                             listing_worker, &pool->workers[i]))
            return 0;
        ++pool->started;
    }
    cu_mutex_lock(pool->mutex);
    pool->ready = 1;
    cu_cond_broadcast(pool->work);
    cu_mutex_unlock(pool->mutex);
    return 1;
}

static int listing_submit(Pool *pool, ListingJob *job)
{
    int i;
    int accepted;
    accepted = 0;
    cu_mutex_lock(pool->mutex);
    if (!pool->stop && pool->pending < pool->count)
        for (i = 0; i < pool->count; ++i)
            if (pool->slots[i] == NULL) {
                pool->slots[i] = job;
                job->token = 1;
                job->state = 1;
                ++pool->pending;
                FYND_PENDING(pool);
                accepted = 1;
                cu_cond_broadcast(pool->work);
                break;
            }
    cu_mutex_unlock(pool->mutex);
    return accepted;
}

/* Adoption releases capacity, never the arena or stable object. */
static void listing_adopt(Pool *pool, ListingJob *job)
{
    int i;
    if (!job->token)
        return;
    cu_mutex_lock(pool->mutex);
    while (job->state != 3)
        cu_cond_wait(pool->completed, pool->mutex);
    for (i = 0; i < pool->count; ++i)
        if (pool->slots[i] == job) {
            pool->slots[i] = NULL;
            --pool->pending;
            FYND_PENDING(pool);
            break;
        }
    job->token = 0;
    cu_mutex_unlock(pool->mutex);
}

static void listing_release(Pool *pool, ListingJob *job)
{
    size_t i;
    WalkEntry *entry;
    listing_adopt(pool, job);
    if (job->error == 0)
        for (i = 0; i < job->entries.len; ++i) {
            entry = CU_VEC_AT(&job->entries, WalkEntry, i);
            if (entry->prefetch != NULL)
                listing_release(pool, entry->prefetch);
        }
    cu_arena_release(&job->arena);
}

