#include "cu.h"
static void sort_step(void);
#define FYND_SORT_STEP() sort_step()
#define fynd_main sort_fixture_main
#include "../src/fynd.c"
#include <assert.h>

static size_t sort_steps;
static size_t sort_limit;

static void sort_step(void)
{
    ++sort_steps;
    assert(sort_steps <= sort_limit);
}

static unsigned int sort_random(unsigned int *state)
{
    *state = *state * 1664525U + 1013904223U;
    return *state;
}

/* Independent byte/length comparator, not strcmp or the production key path. */
static int reference_compare(const void *left, const void *right)
{
    const WalkEntry *a;
    const WalkEntry *b;
    size_t i;
    unsigned char x;
    unsigned char y;
    a = (const WalkEntry *)left;
    b = (const WalkEntry *)right;
    for (i = 0; i < a->name.len && i < b->name.len; ++i) {
        x = (unsigned char)a->name.ptr[i];
        y = (unsigned char)b->name.ptr[i];
        if (x < y) return -1;
        if (x > y) return 1;
    }
    return a->name.len < b->name.len ? -1 : (a->name.len > b->name.len ? 1 : 0);
}

static void sort_case(size_t count, int shape)
{
    CuArena arena;
    WalkEntry *entries;
    WalkEntry *original;
    WalkEntry *expected;
    ListingJob markers[3];
    char *seen;
    unsigned int random;
    char *name;
    size_t i;
    size_t j;
    size_t length;
    size_t prefix;
    size_t value;
    size_t identity;
    cu_arena_init_with(&arena, 4096, 1);
    entries = CU_PUSH(&arena, WalkEntry, count);
    original = CU_PUSH(&arena, WalkEntry, count);
    expected = CU_PUSH(&arena, WalkEntry, count);
    seen = cu_arena_push_bytes(&arena, count);
    assert(entries != NULL && original != NULL && expected != NULL && seen != NULL);
    for (i = 0; i < count; ++i) seen[i] = 0;
    random = 12345U;
    for (i = 0; i < count; ++i) {
        prefix = shape == 1 ? 4096U : 0U;
        length = shape == 0 ? (size_t)(sort_random(&random) % 40U) : prefix + 8;
        if (shape == 4) length = 4;
        if (shape == 5) length = 1;
        name = cu_arena_push_bytes(&arena, length + 1);
        assert(name != NULL);
        if (shape == 0) {
            for (j = 0; j < length; ++j)
                name[j] = (char)(1U + sort_random(&random) % 255U);
            name[length] = 0;
        } else if (shape == 4)
            memcpy(name, "same", 5);
        else if (shape == 5) {
            name[0] = (char)(1U + (unsigned int)(i % 255));
            name[1] = 0;
        } else {
            memset(name, 'a', prefix);
            if (shape == 2) value = count - i;
            else if (shape == 3) value = i <= count / 2 ? i : count - 1 - i;
            else value = i;
            assert(snprintf(name + prefix, length - prefix + 1, "%08lu",
                            (unsigned long)value) == 8);
        }
        entries[i].name = cu_str_n(name, length);
        entries[i].kind = (CuDirKind)(i % 4);
        entries[i].prefetch = &markers[i % 3];
        entries[i].eligible = (int)i;
        original[i] = entries[i];
        expected[i] = entries[i];
    }
    qsort(expected, count, sizeof(WalkEntry), reference_compare);
    sort_steps = 0;
    sort_limit = count * 256 + 1024;
    entry_sort(entries, count);
    for (i = 0; i < count; ++i) {
        assert(reference_compare(&entries[i], &expected[i]) == 0);
        identity = (size_t)entries[i].eligible;
        assert(identity < count && seen[identity] == 0);
        seen[identity] = 1;
        assert(entries[i].name.ptr == original[identity].name.ptr);
        assert(entries[i].name.len == original[identity].name.len);
        assert(entries[i].kind == original[identity].kind);
        assert(entries[i].prefetch == original[identity].prefetch);
    }
    cu_arena_release(&arena);
}

int main(void)
{
    static const size_t sizes[] = {1, 2, 15, 16, 17, 31, 127, 257, 4096};
    size_t i;
    int shape;
    sort_steps = 0;
    sort_limit = 1024;
    entry_sort(NULL, 0);
    for (shape = 0; shape < 6; ++shape)
        for (i = 0; i < sizeof sizes / sizeof sizes[0]; ++i)
            sort_case(sizes[i], shape);
    sort_case(10000, 2);
    sort_case(10000, 3);
    puts("PASS sort order, permutation, payload, byte, prefix, and work-bound cases");
    return 0;
}

