#ifndef FYND_SORT_PROBE_H
#define FYND_SORT_PROBE_H
#include <assert.h>
#include <stdlib.h>
#include <string.h>
#include "fynd.h"
int fynd_sort_probe(int argc, char **argv, FILE *out, FILE *err);
#define fynd_main fynd_sort_probe
#include "../src/fynd.c"
#undef fynd_main

static int sort_reference_less(const WalkEntry *left, const WalkEntry *right)
{
    size_t i;
    unsigned char a;
    unsigned char b;
    for (i = 0; i < left->name.len && i < right->name.len; ++i) {
        a = (unsigned char)left->name.ptr[i];
        b = (unsigned char)right->name.ptr[i];
        if (a < b) return 1;
        if (a > b) return 0;
    }
    return left->name.len < right->name.len;
}

static void check_sort_bytes(const unsigned char *data, size_t size)
{
    WalkEntry entries[64];
    WalkEntry expected[64];
    WalkEntry original[64];
    WalkEntry saved;
    char *names[64];
    char seen[64];
    size_t count;
    size_t at;
    size_t i;
    size_t j;
    size_t length;
    size_t prefix;
    size_t identity;
    /* Invalid identities expose missing record writes rather than hiding them. */
    saved.name = cu_str_n("unwritten", 9);
    saved.kind = CU_DIR_OTHER;
    saved.prefetch = NULL;
    saved.eligible = -1;
    for (i = 0; i < 64; ++i) {
        entries[i] = saved;
        expected[i] = saved;
        original[i] = saved;
    }
    if (size == 0) {
        entry_sort(NULL, 0);
        return;
    }
    count = (size_t)data[0] % 65;
    prefix = size > 1 && (data[1] & 1) ? 40U : 0U;
    at = 1;
    for (i = 0; i < count; ++i) {
        seen[i] = 0;
        length = prefix + (size_t)data[at++ % size] % (95 - prefix);
        names[i] = (char *)malloc(length + 1);
        if (names[i] == NULL) {
            for (j = 0; j < i; ++j) free(names[j]);
            return;
        }
        memset(names[i], 'p', prefix);
        for (j = prefix; j < length; ++j) {
            names[i][j] = (char)data[at++ % size];
            if (names[i][j] == 0) names[i][j] = 1;
        }
        names[i][length] = 0;
        entries[i].name = cu_str_n(names[i], length);
        entries[i].kind = CU_DIR_FILE;
        entries[i].prefetch = NULL;
        entries[i].eligible = (int)i;
        original[i] = entries[i];
        /* Insert this initialized record into the already built oracle prefix. */
        saved = entries[i];
        j = i;
        while (j != 0 && sort_reference_less(&saved, &expected[j - 1])) {
            expected[j] = expected[j - 1];
            --j;
        }
        expected[j] = saved;
    }
    entry_sort(entries, count);
    for (i = 0; i < count; ++i) {
        assert(!sort_reference_less(&entries[i], &expected[i]));
        assert(!sort_reference_less(&expected[i], &entries[i]));
        identity = (size_t)entries[i].eligible;
        assert(identity < count && seen[identity] == 0);
        seen[identity] = 1;
        assert(entries[i].name.ptr == original[identity].name.ptr);
        assert(entries[i].name.len == original[identity].name.len);
        assert(entries[i].kind == CU_DIR_FILE && entries[i].prefetch == NULL);
    }
    for (i = 0; i < count; ++i) free(names[i]);
}
#endif

