    unsigned char data[4];
    size_t i;
    size_t j;
    size_t count;
    check_sort_bytes(NULL, 0);
    for (count = 0; count < 5; ++count)
        for (i = 0; i < 4; ++i)
            for (j = 0; j < 4; ++j) {
                data[0] = (unsigned char)count;
                data[1] = 2;
                data[2] = alphabet[i];
                data[3] = alphabet[j];
                check_sort_bytes(data, sizeof data);
